#ifndef CSM_UISTATE_H
#define CSM_UISTATE_H

#include <stddef.h>

/* The sort columns of the list, in the order of enum tui_sort. */
#define UI_SORTS 5

/* What the TUI remembers between runs. */
struct ui_state {
	size_t sort;
	int reverse;
	char *filter;		/* never NULL */
	char *selected;		/* a session directory's name, or NULL */
	size_t split;		/* the list's share of the panels, in 1/1000 */
};

void ui_state_default(struct ui_state *st);
void ui_state_parse(struct ui_state *st, const char *data, size_t len);
char *ui_state_text(const struct ui_state *st);
char *ui_state_path(const char *home);
int ui_state_load(const char *path, struct ui_state *st);
void ui_state_free(struct ui_state *st);

#endif
